-- Deferred data: only materialize requested map or ID bucket.
local function lazy(factories, bucket)
 local loaded={}
 return setmetatable({}, {__index=function(t,k)
  local b=bucket(k); if b==nil then return end
  if not loaded[b] then
   local factory=factories[b]; if not factory then return end
   local values=factory(); for id,v in pairs(values) do rawset(t,id,v) end
   loaded[b]=true; factories[b]=nil
  end
  return rawget(t,k)
 end})
end
local function numeric(k) if type(k)=='number' then return math.floor(k/64) end end
local function identity(k) return k end
